const response = $input.first().json;
const reservations = Array.isArray(response) ? response : [];

return reservations.map(r => ({
  json: {
    reservation_id: r.id,
    guest_phone: r.guest_phone,
    whatsapp_number_id: r.properties?.whatsapp_number_id || '',
    wa_payload: JSON.stringify({
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: r.guest_phone,
      type: 'template',
      template: {
        name: 'followup_checkin',
        language: { code: 'it' },
        components: [{
          type: 'body',
          parameters: [
            { type: 'text', text: r.guest_name || 'Ospite' },
            { type: 'text', text: r.properties?.nome || 'la struttura' }
          ]
        }]
      }
    })
  }
}));
